// Budget Gate — decide how many DMs and invites we can send today.
// Reads current counters, resets them if the day/week has rolled over,
// and outputs a single item with the available budget.

const rows = $input.all();
const counters = rows[0]?.json || {};

function todayISO() {
  const d = new Date();
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function mondayISO() {
  const d = new Date();
  const day = d.getUTCDay(); // 0=Sun, 1=Mon
  const diff = day === 0 ? -6 : 1 - day;
  d.setUTCDate(d.getUTCDate() + diff);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${dd}`;
}

const today = todayISO();
const weekStart = mondayISO();

// Reset daily count if new day
let dmsSentToday = Number(counters.dms_sent_today) || 0;
if (counters.date !== today) dmsSentToday = 0;

// Reset weekly count if new week
let invitesSentThisWeek = Number(counters.invites_sent_this_week) || 0;
let invitesSentToday_derived = 0; // we'll track daily invites via a separate counter if needed later
if (counters.week_start !== weekStart) invitesSentThisWeek = 0;

const dmDailyCap       = Number(counters.dm_daily_cap)       || 20;
const inviteDailyCap   = Number(counters.invite_daily_cap)   || 20;
const inviteWeeklyCap  = Number(counters.invite_weekly_cap)  || 100;

const dmsAvailable     = Math.max(0, dmDailyCap - dmsSentToday);
const invitesAvailable = Math.max(
  0,
  Math.min(inviteDailyCap, inviteWeeklyCap - invitesSentThisWeek)
);

return [{
  json: {
    today,
    week_start: weekStart,
    dms_sent_today: dmsSentToday,
    invites_sent_this_week: invitesSentThisWeek,
    dm_daily_cap: dmDailyCap,
    invite_daily_cap: inviteDailyCap,
    invite_weekly_cap: inviteWeeklyCap,
    dms_available: dmsAvailable,
    invites_available: invitesAvailable,
    stop_dms: dmsAvailable === 0,
    stop_invites: invitesAvailable === 0,
    stop_all: dmsAvailable === 0 && invitesAvailable === 0
  }
}];

// Cap the leads pulled to today's budget.
// Split into DM-eligible (1st°) and Invite-eligible (everyone else).
// Prioritize 1st° first because DMs are lower-risk than invites.

const leads = $input.all();
const gate = $('Budget Gate').first().json;

const dmsAvailable     = gate.dms_available;
const invitesAvailable = gate.invites_available;

const dmCandidates = leads
  .filter(l => l.json.network_distance === 'DISTANCE_1')
  .slice(0, dmsAvailable)
  .map(l => ({ json: { ...l.json, outreach_type: 'dm' } }));

const inviteCandidates = leads
  .filter(l => l.json.network_distance !== 'DISTANCE_1')
  .slice(0, invitesAvailable)
  .map(l => ({ json: { ...l.json, outreach_type: 'invite' } }));

return [...dmCandidates, ...inviteCandidates];

