// Merge AI-generated messages back with the original lead data.
// The AI Agent output arrives on `.output` — parse it and enforce length caps.

const items = $input.all();

return items.map((item, i) => {
  const leadItem = $('Cap & Tag Outreach Type').all()[i];
  const lead = leadItem?.json || {};

  let ai = item.json.output || item.json;
  if (typeof ai === 'string') {
    try { ai = JSON.parse(ai.replace(/```json|```/g, '').trim()); }
    catch { ai = {}; }
  }

  const dmText = (ai.dm_text || '').slice(0, 300);
  const noteText = (ai.note_text || '').slice(0, 200); // hard cap 200 chars for invite note

  return {
    json: {
      ...lead,
      dm_text: dmText,
      note_text: noteText
    }
  };
});

// Count how many DMs and invites were actually sent (based on merged results).
// Add those counts to the pre-existing counter values.

const gate = $('Budget Gate').first().json;
const results = $input.all();

let dmsSent = 0;
let invitesSent = 0;

for (const r of results) {
  const type = r.json.last_action;
  if (type === 'dm') dmsSent++;
  else if (type === 'invite') invitesSent++;
}

return [{
  json: {
    date: gate.today,
    week_start: gate.week_start,
    dms_sent_today: gate.dms_sent_today + dmsSent,
    invites_sent_this_week: gate.invites_sent_this_week + invitesSent,
    dm_daily_cap: gate.dm_daily_cap,
    invite_daily_cap: gate.invite_daily_cap,
    invite_weekly_cap: gate.invite_weekly_cap,
    dms_sent_this_run: dmsSent,
    invites_sent_this_run: invitesSent
  }
}];

